import{_ as a,o as n,c as t,am as i}from"./chunks/framework.I6SilTJy.js";const p=JSON.parse('{"title":"Glossaire","description":"","frontmatter":{"titre":"Glossaire"},"headers":[],"relativePath":"glossaire.md","filePath":"glossaire.md"}'),o={name:"glossaire.md"};function r(s,e,l,u,d,c){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="glossaire" tabindex="-1">Glossaire <a class="header-anchor" href="#glossaire" aria-label="Permalink to &quot;Glossaire&quot;">​</a></h1><h3 id="agent-de-code" tabindex="-1">Agent de code <a class="header-anchor" href="#agent-de-code" aria-label="Permalink to &quot;Agent de code&quot;">​</a></h3><p>Agent qui lit, modifie et exécute du code dans un dépôt (Copilot, Claude Code, Codex, Cursor…).</p><h3 id="backfill-rattrapage" tabindex="-1">Backfill (rattrapage) <a class="header-anchor" href="#backfill-rattrapage" aria-label="Permalink to &quot;Backfill (rattrapage)&quot;">​</a></h3><p>Recharger des journées passées d&#39;un pipeline, après un incident ou un changement de calcul. Il n&#39;est sûr que si le chargement est idempotent.</p><h3 id="boucle-agentique" tabindex="-1">Boucle agentique <a class="header-anchor" href="#boucle-agentique" aria-label="Permalink to &quot;Boucle agentique&quot;">​</a></h3><p>Le cycle demande → le modèle choisit un tool → le harness l&#39;exécute → le résultat entre dans le contexte → on recommence si besoin.</p><h3 id="ci-integration-continue" tabindex="-1">CI (intégration continue) <a class="header-anchor" href="#ci-integration-continue" aria-label="Permalink to &quot;CI (intégration continue)&quot;">​</a></h3><p>Les vérifications lancées automatiquement à chaque changement du code (construire, tester) avant qu&#39;il parte en production.</p><h3 id="context-window" tabindex="-1">Context window <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;Context window&quot;">​</a></h3><p>Tout ce que le modèle « voit » au moment de répondre : consignes, historique, pièces jointes, résultats des tools.</p><h3 id="contrat-de-donnees" tabindex="-1">Contrat de données <a class="header-anchor" href="#contrat-de-donnees" aria-label="Permalink to &quot;Contrat de données&quot;">​</a></h3><p>L&#39;accord écrit entre l&#39;équipe qui produit une donnée et celles qui la consomment : colonnes, formats, fréquence, et comment un changement est annoncé.</p><h3 id="dbt" tabindex="-1">dbt <a class="header-anchor" href="#dbt" aria-label="Permalink to &quot;dbt&quot;">​</a></h3><p>Outil qui transforme les données dans l&#39;entrepôt avec des requêtes SQL versionnées (les modèles), les teste et les documente.</p><h3 id="duckdb" tabindex="-1">DuckDB <a class="header-anchor" href="#duckdb" aria-label="Permalink to &quot;DuckDB&quot;">​</a></h3><p>Moteur de base de données analytique qui tourne dans un fichier local, sans serveur : celui du pipeline de l&#39;atelier.</p><h3 id="grain" tabindex="-1">Grain <a class="header-anchor" href="#grain" aria-label="Permalink to &quot;Grain&quot;">​</a></h3><p>Ce que représente une ligne d&#39;une table (« une ligne par séjour », « une ligne par paiement »). Un grain flou donne des chiffres qui changent selon qui les calcule.</p><h3 id="harness" tabindex="-1">Harness <a class="header-anchor" href="#harness" aria-label="Permalink to &quot;Harness&quot;">​</a></h3><p>Tout le logiciel autour du modèle : consignes, mémoire, tools, enchaînement des étapes. Deux assistants sur le même modèle diffèrent par leur harness.</p><h3 id="human-in-the-loop" tabindex="-1">Human-in-the-loop <a class="header-anchor" href="#human-in-the-loop" aria-label="Permalink to &quot;Human-in-the-loop&quot;">​</a></h3><p>Un humain qualifié valide la sortie de l&#39;IA <em>avant</em> qu&#39;elle soit utilisée.</p><h3 id="idempotence" tabindex="-1">Idempotence <a class="header-anchor" href="#idempotence" aria-label="Permalink to &quot;Idempotence&quot;">​</a></h3><p>Un traitement est idempotent quand le relancer donne le même résultat : une relance après incident ne crée pas de doublons.</p><h3 id="instructions-projet" tabindex="-1">Instructions projet <a class="header-anchor" href="#instructions-projet" aria-label="Permalink to &quot;Instructions projet&quot;">​</a></h3><p>Fichier versionné dans le dépôt, chargé à chaque session : conventions, commandes, pièges (<code>AGENTS.md</code>, <code>CLAUDE.md</code> pour Claude Code). C&#39;est l&#39;équivalent dev des instructions personnalisées.</p><h3 id="jointure-qui-multiplie-les-lignes-fan-out" tabindex="-1">Jointure qui multiplie les lignes (fan-out) <a class="header-anchor" href="#jointure-qui-multiplie-les-lignes-fan-out" aria-label="Permalink to &quot;Jointure qui multiplie les lignes (fan-out)&quot;">​</a></h3><p>Une jointure vers une table qui a plusieurs lignes par clé : chaque ligne de départ est répétée, et les comptages gonflent.</p><h3 id="lignage-lineage" tabindex="-1">Lignage (lineage) <a class="header-anchor" href="#lignage-lineage" aria-label="Permalink to &quot;Lignage (lineage)&quot;">​</a></h3><p>Le chemin d&#39;une donnée, de sa source aux tableaux de bord qui l&#39;utilisent. Il dit où chercher quand un chiffre est faux, et ce qu&#39;un changement va toucher.</p><h3 id="modele-incremental" tabindex="-1">Modèle incrémental <a class="header-anchor" href="#modele-incremental" aria-label="Permalink to &quot;Modèle incrémental&quot;">​</a></h3><p>Un modèle dbt qui n&#39;ajoute ou ne remplace que les nouvelles données à chaque exécution, au lieu de tout reconstruire.</p><h3 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h3><p>Les actions autorisées à l&#39;agent (lire, écrire, lancer une commande, accéder au réseau).</p><h3 id="profilage" tabindex="-1">Profilage <a class="header-anchor" href="#profilage" aria-label="Permalink to &quot;Profilage&quot;">​</a></h3><p>Décrire une source avant de l&#39;utiliser : types, valeurs vides, valeurs distinctes, minimum et maximum, doublons, unités, fuseaux.</p><h3 id="runbook" tabindex="-1">Runbook <a class="header-anchor" href="#runbook" aria-label="Permalink to &quot;Runbook&quot;">​</a></h3><p>La fiche d&#39;exploitation d&#39;un pipeline : comment il tourne, et pour chaque incident connu, le symptôme, la vérification, quoi faire et qui prévenir.</p><h3 id="schema-en-etoile" tabindex="-1">Schéma en étoile <a class="header-anchor" href="#schema-en-etoile" aria-label="Permalink to &quot;Schéma en étoile&quot;">​</a></h3><p>Une table de faits (les événements à compter, à un grain donné) entourée de tables de dimensions (hôtel, date…) qui servent à filtrer et regrouper.</p><h3 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h3><p>Une conversation ; elle accumule du contexte, utile ou parasite.</p><h3 id="staging" tabindex="-1">Staging <a class="header-anchor" href="#staging" aria-label="Permalink to &quot;Staging&quot;">​</a></h3><p>La première couche de modèles : la source renommée, typée et nettoyée, une vue par source, sans règle métier.</p><h3 id="test-de-donnees" tabindex="-1">Test de données <a class="header-anchor" href="#test-de-donnees" aria-label="Permalink to &quot;Test de données&quot;">​</a></h3><p>Une règle vérifiée sur les données elles-mêmes (unicité, valeurs permises, référentiel) à chaque construction.</p><h3 id="test-unitaire-dbt" tabindex="-1">Test unitaire (dbt) <a class="header-anchor" href="#test-unitaire-dbt" aria-label="Permalink to &quot;Test unitaire (dbt)&quot;">​</a></h3><p>Un test qui donne au modèle des données d&#39;entrée écrites à la main et compare sa sortie à celle attendue : il vérifie le code, pas les données.</p><h3 id="token" tabindex="-1">Token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Token&quot;">​</a></h3><p>Morceau de mot traité par le modèle ; c&#39;est aussi l&#39;unité de facturation (≈ ¾ de mot en anglais).</p><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><p>Capacités que le modèle peut appeler pendant sa réponse : recherche web, calcul, lecture de fichiers, Jira, Figma… (<em>tool calling</em>).</p><h3 id="utc" tabindex="-1">UTC <a class="header-anchor" href="#utc" aria-label="Permalink to &quot;UTC&quot;">​</a></h3><p>Le temps universel, sans fuseau. Un horodatage en UTC tombe parfois un autre jour qu&#39;en heure de Paris : on le convertit avant de regrouper par jour.</p>',55)])])}const m=a(o,[["render",r]]);export{p as __pageData,m as default};
